  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/node_modules/@deepseek-ai/dsh/lib/bin.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/node_modules/@deepseek-ai/dsh/lib/bin.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/node_modules/@deepseek-ai/dsh/lib/bin.js" $args
  } else {
    & "node$exe"  "$basedir/node_modules/@deepseek-ai/dsh/lib/bin.js" $args
  }
  $ret=$LASTEXITCODE
}
exit $ret
